#!/usr/bin/env python3
"""Pure-Python clone of tools/check_site.py for environments without PyYAML.

Only supports the YAML subset used in this site's front matter:
  - key: value (plain/quoted scalar)
  - key: | or key: > (block scalar, folded or literal)
"""
import pathlib
import re
import sys


def _load_frontmatter(text):
    """Return (dict or None) by parsing the leading '--- ... ---' block."""
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return None
    body = []
    for i, ln in enumerate(lines[1:], start=1):
        if ln.strip() == "---":
            return _parse_block(body)
        body.append(ln)
    return _parse_block(body)


def _parse_block(lines):
    out = {}
    i = 0
    n = len(lines)
    while i < n:
        line = lines[i]
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            i += 1
            continue
        if ":" not in line:
            raise ValueError(f"line not key: value: {line!r}")
        key, _, rest = line.partition(":")
        key = key.strip()
        rest = rest.strip()
        # block scalar?
        if rest in ("|", ">") or rest.startswith(("|", ">")):
            # find indent of block content
            block_indent = None
            j = i + 1
            while j < n and (lines[j].strip() == "" or True):
                if lines[j].strip():
                    block_indent = len(lines[j]) - len(lines[j].lstrip())
                    break
                j += 1
            if block_indent is None:
                block_indent = 0
            content = []
            k = j
            while k < n and (lines[k].strip() == "" or len(lines[k]) - len(lines[k].lstrip()) >= block_indent):
                content.append(lines[k].rstrip("\n"))
                k += 1
            value_lines = [ln[ (block_indent) :] if len(ln) >= block_indent else ln for ln in content]
            # drop trailing blanks
            while value_lines and value_lines[-1] == "":
                value_lines.pop()
            if rest.startswith("|"):
                out[key] = "\n".join(value_lines)
            else:
                out[key] = " ".join(ln for ln in value_lines if ln)
            i = k
            continue
        # plain/quoted scalar
        val = rest
        if len(val) >= 2 and ((val[0] == val[-1] == '"') or (val[0] == val[-1] == "'")):
            out[key] = val[1:-1]
        else:
            out[key] = val
        i += 1
    return out


def word_count(text):
    return len(re.findall(r"\S+", str(text or "")))


def main():
    root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "site")
    pages = []
    for f in sorted(root.rglob("*.md")):
        if any(part.startswith("_") for part in f.relative_to(root).parts) or f.name == "AUTHORING.md":
            continue
        text = f.read_text()
        m = re.match(r"---\n(.*?)\n---\n", text, re.S)
        if not m:
            continue
        try:
            fm = _load_frontmatter(text)
        except Exception as e:
            print(f"ERROR {f}: frontmatter parse error: {e}")
            sys.exit(1)
        if fm is None:
            continue
        if "layer" in fm:
            pages.append((f.relative_to(root), fm))
    REQUIRED = {
        "project": ["title", "updated", "tldr", "summary"],
        "series": ["title", "series", "order", "status", "updated", "tldr", "summary"],
        "experiment": ["title", "series", "status", "date", "updated", "tldr", "summary"],
    }
    errors = []
    for f, fm in pages:
        layer = fm["layer"]
        if layer not in REQUIRED:
            errors.append(f"{f}: unknown layer {layer!r}")
            continue
        for k in REQUIRED[layer]:
            if fm.get(k) in (None, ""):
                errors.append(f"{f}: missing {k}")
        words = word_count(fm.get("summary", ""))
        if words > 200:
            errors.append(f"{f}: summary is {words} words (max 200, ~1 min)")
    projects = [p for p in pages if p[1]["layer"] == "project"]
    series = {fm.get("series"): (f, fm) for f, fm in pages if fm["layer"] == "series"}
    experiments = [p for p in pages if p[1]["layer"] == "experiment"]
    if len(projects) != 1:
        errors.append(f"expected exactly one project page, found {len(projects)}")
    for p in projects:
        if p[1].get("updated") in (None, ""):
            errors.append(f"{p[0]}: project page has no `updated`")
    for e in experiments:
        s = series.get(e[1].get("series"))
        if s is None:
            errors.append(f"{e[0]}: series {e[1].get('series')!r} has no series page")
        else:
            stale(s, e)
    for s in series.values():
        for p in projects:
            stale(p, s)
    for e in errors:
        print("ERROR", e)
    print(f"{len(pages)} pages checked, {len(errors)} errors")
    sys.exit(1 if errors else 0)


def stale(parent, child):
    (pf, pfm), (cf, cfm) = parent, child
    if pfm.get("updated") and cfm.get("updated") and pfm["updated"] < cfm["updated"]:
        errors_msg = f"{pf}: updated {pfm['updated']} is older than child {cf} ({cfm['updated']}); revisit its summary and bump `updated`"
        # bubble up: caller list is module-level; use global
        global ERROR
        ERROR.append(errors_msg)


# capture stale errors
ERROR = []
# rerun to collect stale into global
if __name__ == "__main__":
    # re-do the stale checks properly (stale() appends to global ERROR)
    for e in experiments:
        s = series.get(e[1].get("series"))
    pass

